                        "curl --fail --silent --show-error --location \\",
                        "  https://github.com/joshyorko/rcc/releases/download/v18.19.3/rcc-linux64 \\",
                        '  --output "$destination"',
                        "echo '7e588c01751ca2ae15ba13ef67f2f4b7567697a5a8389737059a73936f509428  '"
